// Package external is a separate Go module that consumes ai-rulez only through
// its public API (pkg/airulez), the way an embedding service would. It exists so
// that a change which breaks what an outside module can import or compile fails
// here, which no test inside the main module can show: the main module can reach
// internal/ and a consumer cannot.
//
// Run it with `go test ./...` from this directory (the main module's own test
// run skips it, being a different module).
package external

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/Goldziher/ai-rulez/v5/pkg/airulez"
)

func TestAServiceCanPlanSourcesThatExistOnlyInMemory(t *testing.T) {
	// Arrange
	ctx := context.Background()
	ws := airulez.NewMemWorkspace()
	ws.Set(".ai-rulez/config.toml", "version = \"4.0\"\nname = \"consumer\"\npresets = [\"claude\", \"cursor\"]\n", 0o644)
	ws.Set(".ai-rulez/rules/style.md", "# Style\n\nBe concise.\n", 0o644)

	// Act
	project, err := airulez.Load(ctx, airulez.Options{Workspace: ws, Runner: airulez.DenyAll()})
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	plan, err := project.Plan(ctx, airulez.PlanOptions{})
	if err != nil {
		t.Fatalf("Plan: %v", err)
	}

	// Assert
	if plan.Digest == "" || len(plan.Digest) != 64 {
		t.Errorf("Digest = %q, want a SHA-256 hex string", plan.Digest)
	}
	paths := map[string]bool{}
	for _, f := range plan.Files {
		paths[f.Path] = true
	}
	for _, want := range []string{"CLAUDE.md", ".cursor/rules/style.mdc"} {
		if !paths[want] {
			t.Errorf("plan lacks %s; has %v", want, plan.Files)
		}
	}
	doc, err := plan.JSON()
	if err != nil || !strings.Contains(string(doc), `"schema"`) {
		t.Errorf("JSON() = %q, %v", doc, err)
	}
}

func TestAServicePlanSeesTheOutputsAlreadyInItsWorkspace(t *testing.T) {
	// Arrange: a tree that was generated for claude and cursor, whose config now
	// keeps claude only.
	ctx := context.Background()
	ws := airulez.NewMemWorkspace()
	ws.Set(".ai-rulez/config.toml", "version = \"4.0\"\nname = \"consumer\"\npresets = [\"claude\"]\n", 0o644)
	ws.Set(".ai-rulez/rules/style.md", "# Style\n\nBe concise.\n", 0o644)
	ws.Set(".ai-rulez/.generated-manifest.json", `{"version":"1","files":[".cursor/rules/style.mdc"]}`, 0o644)
	cursor := "---\nalwaysApply: true\n---\n<!-- Generated by ai-rulez. Edit the source, not this file. -->\n# Style\n\nBe concise.\n"
	ws.Set(".cursor/rules/style.mdc", cursor, 0o644)
	sum := sha256.Sum256([]byte(cursor))
	ws.Set(".ai-rulez/.generated-manifest.local.json",
		`{"version":"1","files":[],"digests":{".cursor/rules/style.mdc":"`+hex.EncodeToString(sum[:])+`"}}`, 0o644)
	project, err := airulez.Load(ctx, airulez.Options{Workspace: ws, Runner: airulez.DenyAll()})
	if err != nil {
		t.Fatalf("Load: %v", err)
	}

	// Act
	plan, err := project.Plan(ctx, airulez.PlanOptions{})
	if err != nil {
		t.Fatalf("Plan: %v", err)
	}

	// Assert: the cursor output of the workspace is taken back, though none of it is on the disk of this process.
	found := false
	for _, r := range plan.Removals {
		found = found || (r.Path == ".cursor/rules/style.mdc" && r.Reason == "stale")
	}
	if !found {
		t.Errorf("removals = %v, want the stale cursor output", plan.Removals)
	}
}

func TestAServiceCannotWriteToAWorkspaceThatIsNotADirectory(t *testing.T) {
	ctx := context.Background()
	ws := airulez.NewMemWorkspace()
	ws.Set(".ai-rulez/config.toml", "version = \"4.0\"\nname = \"consumer\"\npresets = [\"claude\"]\n", 0o644)
	project, err := airulez.Load(ctx, airulez.Options{Workspace: ws})
	if err != nil {
		t.Fatal(err)
	}

	_, err = project.Generate(ctx, airulez.GenerateOptions{Mode: airulez.Write})

	var apiErr *airulez.Error
	if !asError(err, &apiErr) || apiErr.Code != airulez.CodeDiskRequired {
		t.Fatalf("Generate = %v, want a %s error", err, airulez.CodeDiskRequired)
	}
}

func asError(err error, target **airulez.Error) bool {
	for err != nil {
		if e, ok := err.(*airulez.Error); ok { //nolint:errorlint // the facade returns its error directly
			*target = e
			return true
		}
		u, ok := err.(interface{ Unwrap() error })
		if !ok {
			return false
		}
		err = u.Unwrap()
	}
	return false
}

// recordingRunner is a Runner an outside module can write: it only needs the
// public Spec and Result types.
type recordingRunner struct{ argv [][]string }

func (r *recordingRunner) Run(_ context.Context, spec airulez.Spec) airulez.Result {
	r.argv = append(r.argv, spec.Argv)
	return airulez.Result{Status: airulez.StatusUnavailable, ExitCode: -1, Err: errors.New("no commands in this service")}
}

func TestAServiceCanImplementItsOwnRunner(t *testing.T) {
	ctx := context.Background()
	run := &recordingRunner{}
	var asRunner airulez.Runner = run
	ws := airulez.NewMemWorkspace()
	ws.Set(".ai-rulez/config.toml", "version = \"4.0\"\nname = \"consumer\"\npresets = [\"claude\"]\n", 0o644)

	project, err := airulez.Load(ctx, airulez.Options{Workspace: ws, Runner: asRunner})
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if _, err := project.Plan(ctx, airulez.PlanOptions{}); err != nil {
		t.Fatalf("Plan: %v", err)
	}
	if _, err := airulez.GitSnapshot(ctx, t.TempDir(), "HEAD", asRunner); err == nil {
		t.Fatal("a snapshot with a runner that starts nothing must fail")
	}
	if len(run.argv) == 0 || run.argv[0][0] != "git" {
		t.Errorf("the service's runner was not asked to start the version control tool: %v", run.argv)
	}
}

func TestAServiceCanLockAProjectDirectoryAndCheckIt(t *testing.T) {
	// Arrange: a project directory with one rule and no lock yet.
	ctx := context.Background()
	home := t.TempDir()
	t.Setenv("HOME", home)
	t.Setenv("XDG_CACHE_HOME", filepath.Join(home, ".cache"))
	dir := t.TempDir()
	for name, content := range map[string]string{
		".ai-rulez/config.toml":    "version = \"4.0\"\nname = \"consumer\"\npresets = [\"claude\"]\n",
		".ai-rulez/rules/style.md": "# Style\n\nBe concise.\n",
	} {
		path := filepath.Join(dir, filepath.FromSlash(name))
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	ws, err := airulez.DirWorkspace(dir)
	if err != nil {
		t.Fatal(err)
	}
	project, err := airulez.Load(ctx, airulez.Options{Workspace: ws, Runner: airulez.DenyAll(), Env: airulez.MapEnv{Home: home}})
	if err != nil {
		t.Fatalf("Load: %v", err)
	}

	// Act
	res, err := project.Lock(ctx, airulez.LockOptions{Strict: true})
	if err != nil {
		var findings *airulez.FindingsError
		if errors.As(err, &findings) {
			t.Fatalf("Lock refused findings %v", findings.Findings)
		}
		t.Fatalf("Lock: %v", err)
	}
	status, err := project.LockCheck(ctx, airulez.LockCheckOptions{})

	// Assert
	if res.Path != ".ai-rulez/ai-rulez.lock" || res.Tree == "" || len(res.Unpinned) != 0 {
		t.Errorf("Lock = %+v, want the lock file with content pins", res)
	}
	if err != nil || !status.InSync {
		t.Errorf("LockCheck = %+v, %v; want a lock in sync with the sources it was just written from", status, err)
	}
}
